'use client';

import { Download, Printer, WalletCards } from 'lucide-react';
import { format } from 'date-fns';
import type { SalarySlip } from '@peopleos/types';
import { formatMoney } from '@/lib/api';
import { Badge, Button, Card } from './ui';

export function SalarySlipView({ slip, compact = false }: { slip: SalarySlip; compact?: boolean }) { const download = () => { const lines = [`PeopleOS salary slip`, `${slip.employee?.firstName ?? ''} ${slip.employee?.lastName ?? ''}`, `${format(new Date(slip.year, slip.month - 1, 1), 'MMMM yyyy')}`, `Gross salary: ${formatMoney(slip.grossSalary)}`, `Total deductions: ${formatMoney(slip.totalDeductions)}`, `Net salary: ${formatMoney(slip.netSalary)}`]; const blob = new Blob([lines.join('\n')], { type: 'text/plain' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `peopleos-salary-slip-${slip.year}-${slip.month}.txt`; anchor.click(); URL.revokeObjectURL(url); }; return <Card className="print-area overflow-hidden"><div className="flex flex-col gap-4 border-b border-[#e8e4dc] bg-[#fffaf1] p-5 sm:flex-row sm:items-center sm:justify-between sm:p-7"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#1f2229] text-[#d8f25d]"><WalletCards className="h-5 w-5" /></div><div><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#ff725c]">PeopleOS payroll</p><h2 className="font-display text-2xl">Salary slip</h2></div></div><div className="no-print flex gap-2"><Button variant="outline" size="sm" onClick={() => window.print()}><Printer className="h-4 w-4" />Print</Button><Button variant="lime" size="sm" onClick={download}><Download className="h-4 w-4" />Download</Button></div></div><div className="p-5 sm:p-7"><div className="grid gap-5 border-b border-[#eeeae4] pb-6 sm:grid-cols-3"><div><p className="text-[10px] font-bold uppercase tracking-[0.13em] text-[#92939a]">Employee</p><p className="mt-1 text-sm font-bold">{slip.employee ? `${slip.employee.firstName} ${slip.employee.lastName}` : 'Employee'}</p><p className="text-xs text-[#85878d]">{slip.employee?.employeeCode} · {slip.employee?.designation}</p></div><div><p className="text-[10px] font-bold uppercase tracking-[0.13em] text-[#92939a]">Pay period</p><p className="mt-1 text-sm font-bold">{format(new Date(slip.year, slip.month - 1, 1), 'MMMM yyyy')}</p><p className="text-xs text-[#85878d]">Monthly payroll cycle</p></div><div><p className="text-[10px] font-bold uppercase tracking-[0.13em] text-[#92939a]">Payment status</p><div className="mt-2"><Badge tone={slip.paymentStatus === 'PAID' ? 'green' : 'orange'}>{slip.paymentStatus}</Badge></div></div></div><div className="grid gap-8 py-7 md:grid-cols-2"><SalaryColumn title="Earnings" items={[['Basic salary', slip.basicSalary], ['House rent allowance', slip.houseRentAllowance], ['Transport allowance', slip.transportAllowance], ['Performance bonus', slip.performanceBonus]]} totalLabel="Gross salary" total={slip.grossSalary} /><SalaryColumn title="Deductions" items={[['Provident fund', slip.providentFund], ['Professional tax', slip.professionalTax], ['Income tax', slip.incomeTax], ['Other deductions', slip.otherDeductions]]} totalLabel="Total deductions" total={slip.totalDeductions} /></div><div className="flex flex-col gap-3 rounded-2xl bg-[#1f2229] p-5 text-white sm:flex-row sm:items-center sm:justify-between"><div><p className="text-xs text-[#a8aab0]">Net pay</p><p className="mt-1 font-display text-3xl text-[#d8f25d]">{formatMoney(slip.netSalary)}</p></div><p className="text-xs text-[#a8aab0]">{slip.paymentDate ? `Paid ${format(new Date(slip.paymentDate), 'd MMM yyyy')}` : 'Payment pending'}</p></div>{!compact && <p className="mt-6 text-center text-[11px] text-[#a0a1a6]">This is a computer-generated salary slip from PeopleOS HRMS.</p>}</div></Card>; }
function SalaryColumn({ title, items, totalLabel, total }: { title: string; items: [string, number][]; totalLabel: string; total: number }) { return <div><h3 className="mb-4 font-display text-xl">{title}</h3><div className="space-y-3">{items.map(([label, value]) => <div key={label} className="flex justify-between gap-4 text-sm"><span className="text-[#777982]">{label}</span><span className="tabular-nums font-semibold">{formatMoney(value)}</span></div>)}</div><div className="mt-4 flex justify-between border-t border-[#eeeae4] pt-4 text-sm font-bold"><span>{totalLabel}</span><span className="tabular-nums">{formatMoney(total)}</span></div></div>; }
